import { useEffect, useMemo, useRef, useState, type ChangeEvent, type FormEvent, type ReactNode } from 'react'
import { createRoot } from 'react-dom/client'
import {
  Activity, Apple, ArrowRight, Bell, CalendarDays, Camera, Check, ChevronDown, ChevronRight,
  ClipboardList, CloudSun, Droplets, Edit3, ExternalLink, FileDown, FileUp, Heart,
  HeartPulse, Home, Info, Languages, Leaf, LockKeyhole, Menu, Moon, MoreHorizontal,
  NotebookPen, Pill, Plus, Search, Settings, Share2, ShieldCheck, Sparkles, Sun, Trash2,
  TrendingUp, UserRound, Utensils, X, Zap, GlassWater, Scale, CircleAlert
} from 'lucide-react'
import './styles.css'

type Lang = 'en' | 'ur'
type Theme = 'light' | 'dark' | 'system'
type View = 'home' | 'records' | 'medicines' | 'appointments' | 'notes' | 'favorites' | 'settings' | 'profile'
type ModalType = 'bp' | 'sugar' | 'weight' | 'water' | 'medicine' | 'appointment' | 'note' | 'profile' | 'about' | 'language' | null

type BPRecord = { id: string; systolic: number; diastolic: number; pulse: number; date: string; time: string; note: string }
type SugarRecord = { id: string; value: number; unit: string; meal: string; date: string; time: string; note: string }
type WeightRecord = { id: string; value: number; unit: string; date: string; time: string; note: string }
type Medicine = { id: string; name: string; dosage: string; instructions: string; note: string; reminder: string; repeat: string; image?: string; taken: boolean; createdAt: string }
type Appointment = { id: string; doctor: string; specialty: string; date: string; time: string; reason: string; note: string }
type HealthNote = { id: string; title: string; body: string; category: string; date: string; time: string }
type WaterDay = { date: string; glasses: number; goal: number }
type Profile = { name: string; age: string; bloodGroup: string; healthInfo: string; photo?: string }
type AppData = {
  bp: BPRecord[]; sugar: SugarRecord[]; weight: WeightRecord[]; medicines: Medicine[];
  appointments: Appointment[]; notes: HealthNote[]; water: WaterDay[]; favorites: string[];
  profile: Profile; settings: { lang: Lang; theme: Theme; notifications: boolean }
}

type PromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }> }

type RecordItem = { id: string; kind: string; label: string; value: string; date: string; time: string; note?: string }

const today = () => new Date().toISOString().slice(0, 10)
const nowTime = () => new Date().toTimeString().slice(0, 5)
const id = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
const prettyDate = (value: string) => value ? new Date(`${value}T12:00:00`).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '—'
const shortDate = (value: string) => value ? new Date(`${value}T12:00:00`).toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) : '—'
const readFile = (file: File) => new Promise<string>((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(String(r.result)); r.onerror = reject; r.readAsDataURL(file) })
const viewFromPath = (): View => { const path = window.location.hash.replace(/^#\/?/, '') as View; return ['records', 'medicines', 'appointments', 'notes', 'favorites', 'settings', 'profile'].includes(path) ? path : 'home' }

const initialData: AppData = {
  bp: [{ id: 'seed-bp', systolic: 120, diastolic: 80, pulse: 72, date: today(), time: '09:42', note: 'Feeling good today.' }],
  sugar: [{ id: 'seed-sugar', value: 98, unit: 'mg/dL', meal: 'After meal', date: today(), time: '08:35', note: 'Good level' }],
  weight: [{ id: 'seed-weight', value: 68.5, unit: 'kg', date: today(), time: '09:20', note: '' }],
  medicines: [
    { id: 'med-1', name: 'Paracetamol', dosage: '500 mg', instructions: '1 tablet after food', note: '', reminder: '08:00', repeat: 'Daily', taken: false, createdAt: today() },
    { id: 'med-2', name: 'Vitamin D3', dosage: '1 capsule', instructions: 'After breakfast', note: '', reminder: '09:00', repeat: 'Weekly', taken: true, createdAt: today() },
    { id: 'med-3', name: 'Metformin', dosage: '500 mg', instructions: '1 tablet after food', note: '', reminder: '20:00', repeat: 'Daily', taken: false, createdAt: today() },
  ],
  appointments: [{ id: 'apt-1', doctor: 'Dr. Ali Khan', specialty: 'General Physician', date: today(), time: '10:00', reason: 'Routine checkup', note: '' }],
  notes: [{ id: 'note-1', title: 'Workout plan', body: '30 minutes daily exercise.', category: 'Exercise', date: today(), time: '08:00' }, { id: 'note-2', title: 'Diet plan', body: 'More fruits and vegetables.', category: 'Diet', date: today(), time: '08:10' }],
  water: [{ date: today(), glasses: 5, goal: 8 }],
  favorites: ['bp', 'sugar', 'water', 'medicines'],
  profile: { name: 'Muhammad Usman', age: '28', bloodGroup: 'O+', healthInfo: 'No major issues' },
  settings: { lang: 'en', theme: 'light', notifications: false },
}

const loadData = (): AppData => {
  try {
    const raw = localStorage.getItem('health-saathi-data')
    if (!raw) return initialData
    const saved = JSON.parse(raw) as Partial<AppData>
    return { ...initialData, ...saved, profile: { ...initialData.profile, ...(saved.profile || {}) }, settings: { ...initialData.settings, ...(saved.settings || {}) } }
  } catch { return initialData }
}

const tMap: Record<string, { en: string; ur: string }> = {
  home: { en: 'Home', ur: 'ہوم' }, records: { en: 'Records', ur: 'ریکارڈز' }, medicines: { en: 'Medicines', ur: 'ادویات' }, settings: { en: 'Settings', ur: 'ترتیبات' },
  dashboard: { en: 'Your health, in one calm place.', ur: 'آپ کی صحت، ایک پُرسکون جگہ پر۔' }, greeting: { en: 'Good morning', ur: 'صبح بخیر' }, healthTip: { en: "Today's health tip", ur: 'آج کی صحت کا مشورہ' }, quickAdd: { en: 'Quick add', ur: 'فوری اضافہ' }, seeAll: { en: 'See all', ur: 'سب دیکھیں' }, save: { en: 'Save record', ur: 'ریکارڈ محفوظ کریں' }, cancel: { en: 'Cancel', ur: 'منسوخ' }, recent: { en: 'Recent activity', ur: 'حالیہ سرگرمی' }, water: { en: 'Water', ur: 'پانی' }, bp: { en: 'Blood pressure', ur: 'بلڈ پریشر' }, sugar: { en: 'Blood sugar', ur: 'بلڈ شوگر' }, weight: { en: 'Weight', ur: 'وزن' }, appointments: { en: 'Appointments', ur: 'ملاقاتیں' }, notes: { en: 'Notes', ur: 'نوٹس' }, favorites: { en: 'Favorites', ur: 'پسندیدہ' }, profile: { en: 'Profile', ur: 'پروفائل' }, search: { en: 'Search health, medicines...', ur: 'صحت، ادویات تلاش کریں...' }, today: { en: 'Today', ur: 'آج' }, add: { en: 'Add', ur: 'شامل کریں' }, history: { en: 'Health records', ur: 'صحت کے ریکارڈز' }, install: { en: 'Install app', ur: 'ایپ انسٹال کریں' }, about: { en: 'About Health Saathi', ur: 'ہیلتھ ساتھی کے بارے میں' }, share: { en: 'Share app', ur: 'ایپ شیئر کریں' }, language: { en: 'Language', ur: 'زبان' }, theme: { en: 'Theme / appearance', ur: 'تھیم / ظاہری شکل' }, backup: { en: 'Data / backup', ur: 'ڈیٹا / بیک اپ' }, privacy: { en: 'Privacy', ur: 'رازداری' }, notifications: { en: 'Notifications', ur: 'اطلاعات' }, noData: { en: 'Nothing here yet', ur: 'ابھی یہاں کچھ نہیں' }, addFirst: { en: 'Add your first record', ur: 'اپنا پہلا ریکارڈ شامل کریں' }, taken: { en: 'Taken', ur: 'لی گئی' }, upcoming: { en: 'Upcoming', ur: 'آنے والی' }, good: { en: 'Good morning, take one small step for yourself today.', ur: 'صبح بخیر، آج اپنے لیے ایک چھوٹا سا قدم اٹھائیں۔' }
}

function App() {
  const [data, setData] = useState<AppData>(loadData)
  const [view, setView] = useState<View>(viewFromPath)
  const [modal, setModal] = useState<{ type: ModalType; editId?: string }>({ type: null })
  const [splash, setSplash] = useState(true)
  const [toast, setToast] = useState('')
  const [query, setQuery] = useState('')
  const [recordFilter, setRecordFilter] = useState('All')
  const [installEvent, setInstallEvent] = useState<PromptEvent | null>(null)
  const [searchOpen, setSearchOpen] = useState(false)
  const [waterBump, setWaterBump] = useState(0)
  const [quickOpen, setQuickOpen] = useState(false)

  const tr = (key: string) => tMap[key]?.[data.settings.lang] || key
  const currentWater = data.water.find(x => x.date === today()) || { date: today(), glasses: 0, goal: 8 }

  useEffect(() => {
    localStorage.setItem('health-saathi-data', JSON.stringify(data))
  }, [data])

  useEffect(() => {
    const timer = window.setTimeout(() => setSplash(false), 2200)
    const handleInstall = (event: Event) => { event.preventDefault(); setInstallEvent(event as PromptEvent) }
    window.addEventListener('beforeinstallprompt', handleInstall)
    return () => { window.clearTimeout(timer); window.removeEventListener('beforeinstallprompt', handleInstall) }
  }, [])

  useEffect(() => {
    const onPopState = () => setView(viewFromPath())
    window.addEventListener('hashchange', onPopState)
    return () => window.removeEventListener('hashchange', onPopState)
  }, [])

  useEffect(() => {
    document.documentElement.lang = data.settings.lang === 'ur' ? 'ur' : 'en'
    document.documentElement.dir = data.settings.lang === 'ur' ? 'rtl' : 'ltr'
    document.documentElement.dataset.theme = data.settings.theme === 'system' ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light') : data.settings.theme
  }, [data.settings.lang, data.settings.theme])

  useEffect(() => {
    if ('serviceWorker' in navigator) navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(() => undefined)
  }, [])

  useEffect(() => {
    if (!toast) return
    const timer = window.setTimeout(() => setToast(''), 2800)
    return () => window.clearTimeout(timer)
  }, [toast])

  const navigate = (next: View) => { setView(next); setSearchOpen(false); window.history.replaceState({}, '', next === 'home' ? window.location.pathname : `#/${next}`) }
  const notify = (message: string) => setToast(message)
  const openModal = (type: ModalType, editId?: string) => setModal({ type, editId })
  const closeModal = () => setModal({ type: null })

  const updateWater = (delta: number) => {
    setData(prev => {
      const existing = prev.water.find(x => x.date === today()) || { date: today(), glasses: 0, goal: 8 }
      const next = { ...existing, glasses: Math.max(0, Math.min(existing.goal, existing.glasses + delta)) }
      return { ...prev, water: [...prev.water.filter(x => x.date !== today()), next] }
    })
    setWaterBump(x => x + 1)
  }

  const toggleFavorite = (key: string) => {
    setData(prev => ({ ...prev, favorites: prev.favorites.includes(key) ? prev.favorites.filter(x => x !== key) : [...prev.favorites, key] }))
    notify(data.favorites.includes(key) ? 'Removed from Favorites' : 'Added to Favorites')
  }

  const shareApp = async () => {
    const shareData = { title: 'Health Saathi', text: 'Health Saathi — Your Health, Our Priority', url: window.location.href }
    try {
      if (navigator.share) await navigator.share(shareData)
      else { await navigator.clipboard?.writeText(window.location.href); notify('Share link copied') }
    } catch { /* user dismissed */ }
  }

  const installApp = async () => {
    if (installEvent) { await installEvent.prompt(); setInstallEvent(null); return }
    notify('Use your browser menu to add Health Saathi to your home screen')
  }

  const requestNotifications = async () => {
    if (!('Notification' in window)) { notify('Notifications are not supported in this browser'); return }
    const permission = await Notification.requestPermission()
    setData(prev => ({ ...prev, settings: { ...prev.settings, notifications: permission === 'granted' } }))
    notify(permission === 'granted' ? 'Medicine reminders enabled' : 'Permission not granted — reminders stay in-app')
  }

  const exportData = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `health-saathi-backup-${today()}.json`; link.click(); URL.revokeObjectURL(link.href)
    notify('Backup downloaded')
  }

  const importData = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]; if (!file) return
    try { const parsed = JSON.parse(await file.text()) as AppData; setData({ ...initialData, ...parsed }); notify('Backup restored successfully') } catch { notify('That backup file could not be read') }
    event.target.value = ''
  }

  const records = useMemo<RecordItem[]>(() => [
    ...data.bp.map(x => ({ id: x.id, kind: 'BP', label: 'Blood pressure', value: `${x.systolic}/${x.diastolic} mmHg`, date: x.date, time: x.time, note: x.note })),
    ...data.sugar.map(x => ({ id: x.id, kind: 'Sugar', label: 'Blood sugar', value: `${x.value} ${x.unit}`, date: x.date, time: x.time, note: x.note })),
    ...data.weight.map(x => ({ id: x.id, kind: 'Weight', label: 'Weight', value: `${x.value} ${x.unit}`, date: x.date, time: x.time, note: x.note })),
    ...data.water.map(x => ({ id: x.date, kind: 'Water', label: 'Water', value: `${x.glasses}/${x.goal} glasses`, date: x.date, time: '', note: '' })),
    ...data.appointments.map(x => ({ id: x.id, kind: 'Appointment', label: x.doctor, value: x.specialty, date: x.date, time: x.time, note: x.reason })),
    ...data.notes.map(x => ({ id: x.id, kind: 'Note', label: x.title, value: x.category, date: x.date, time: x.time, note: x.body })),
  ].sort((a, b) => `${b.date}${b.time}`.localeCompare(`${a.date}${a.time}`)), [data])

  const filteredRecords = records.filter(record => recordFilter === 'All' || record.kind === recordFilter)
  const searchResults = useMemo(() => {
    const term = query.toLowerCase().trim()
    if (!term) return []
    const items = [
      ...data.medicines.map(x => ({ title: x.name, sub: `${x.dosage} · ${x.reminder}`, target: 'medicines' as View, icon: Pill })),
      ...records.map(x => ({ title: x.label, sub: `${x.value} · ${prettyDate(x.date)}`, target: 'records' as View, icon: Activity })),
      { title: 'Blood pressure tracker', sub: 'Add a new reading', target: 'home' as View, icon: HeartPulse },
      { title: 'Water tracker', sub: 'Update today\'s glasses', target: 'home' as View, icon: GlassWater },
      { title: 'Appointments', sub: 'Upcoming doctor visits', target: 'appointments' as View, icon: CalendarDays },
    ]
    return items.filter(x => `${x.title} ${x.sub}`.toLowerCase().includes(term)).slice(0, 8)
  }, [query, data.medicines, records])

  const topNav = [
    { key: 'home' as View, label: tr('home'), icon: Home }, { key: 'records' as View, label: tr('records'), icon: ClipboardList }, { key: 'medicines' as View, label: tr('medicines'), icon: Pill }, { key: 'settings' as View, label: tr('settings'), icon: Settings },
  ]

  if (splash) return <Splash lang={data.settings.lang} />

  return <div className="app-frame">
    <div className="ambient ambient-one" /><div className="ambient ambient-two" />
    <aside className="desktop-rail">
      <Brand compact={false} />
      <div className="rail-profile" onClick={() => navigate('profile')}><Avatar profile={data.profile} /><div><strong>{data.profile.name}</strong><span>{data.settings.lang === 'ur' ? 'میری صحت' : 'My health space'}</span></div><ChevronRight size={15} /></div>
      <nav className="rail-nav">{topNav.map(item => <NavButton key={item.key} active={view === item.key} icon={item.icon} label={item.label} onClick={() => navigate(item.key)} />)}<div className="rail-divider" />
        <NavButton active={view === 'appointments'} icon={CalendarDays} label={tr('appointments')} onClick={() => navigate('appointments')} /><NavButton active={view === 'notes'} icon={NotebookPen} label={tr('notes')} onClick={() => navigate('notes')} /><NavButton active={view === 'favorites'} icon={Heart} label={tr('favorites')} onClick={() => navigate('favorites')} />
      </nav>
      <div className="rail-bottom"><div className="mini-tip"><Sparkles size={16} /><span>{data.settings.lang === 'ur' ? 'آپ کی صحت، آپ کی طاقت' : 'Small steps. Better days.'}</span></div><NavButton active={view === 'profile'} icon={UserRound} label={tr('profile')} onClick={() => navigate('profile')} /></div>
    </aside>

    <main className="main-shell">
      <header className="topbar">
        <div className="mobile-brand"><Brand compact /></div>
        <div className="topbar-tools"><button className="search-trigger" onClick={() => setSearchOpen(true)}><Search size={17} /><span>{tr('search')}</span><kbd>⌘ K</kbd></button><button className="icon-btn notification-btn" aria-label="Notifications" onClick={requestNotifications}><Bell size={19} />{data.medicines.some(x => !x.taken) && <i />}</button><button className="avatar-button" onClick={() => navigate('profile')}><Avatar profile={data.profile} /></button></div>
      </header>

      <div className="page-content">
        {view === 'home' && <Dashboard data={data} tr={tr} currentWater={currentWater} waterBump={waterBump} onNavigate={navigate} onOpen={openModal} onWater={updateWater} onFavorite={toggleFavorite} />}
        {view === 'records' && <RecordsPage records={filteredRecords} filter={recordFilter} setFilter={setRecordFilter} onNavigate={navigate} onOpen={openModal} />}
        {view === 'medicines' && <MedicinesPage data={data} setData={setData} onOpen={openModal} notify={notify} onFavorite={toggleFavorite} />}
        {view === 'appointments' && <AppointmentsPage data={data} setData={setData} onOpen={openModal} notify={notify} />}
        {view === 'notes' && <NotesPage data={data} setData={setData} onOpen={openModal} notify={notify} />}
        {view === 'favorites' && <FavoritesPage favorites={data.favorites} onFavorite={toggleFavorite} onNavigate={navigate} />}
        {view === 'profile' && <ProfilePage data={data} setData={setData} onOpen={openModal} notify={notify} />}
        {view === 'settings' && <SettingsPage data={data} setData={setData} onOpen={openModal} onInstall={installApp} installReady={!!installEvent} onNotify={requestNotifications} onShare={shareApp} onExport={exportData} onImport={importData} notify={notify} />}
      </div>
      <footer className="credit"><HeartPulse size={15} /> Developed by Muhammad Usman Channa</footer>
      <BottomNav view={view} navigate={navigate} tr={tr} onAdd={() => setQuickOpen(true)} />
    </main>

    {searchOpen && <SearchOverlay query={query} setQuery={setQuery} results={searchResults} onClose={() => { setSearchOpen(false); setQuery('') }} onNavigate={navigate} />}
    {quickOpen && <QuickSheet close={() => setQuickOpen(false)} onOpen={openModal} />}
    {modal.type && <ModalRouter modal={modal} data={data} setData={setData} close={closeModal} notify={notify} onNotify={requestNotifications} />}
    {toast && <div className="toast"><Check size={17} /><span>{toast}</span></div>}
  </div>
}

function Splash({ lang }: { lang: Lang }) { return <div className="splash"><div className="splash-orbit orbit-a" /><div className="splash-orbit orbit-b" /><div className="splash-card"><Brand compact={false} large /><div className="splash-heart"><HeartPulse size={78} strokeWidth={1.3} /><div className="pulse-line"><span /></div></div><p>{lang === 'ur' ? 'آپ کی صحت، ہماری ترجیح' : 'Your Health · Our Priority'}</p><small>Developed by Muhammad Usman Channa</small></div><div className="splash-leaf leaf-left">✦</div><div className="splash-leaf leaf-right">✦</div></div> }
function Brand({ compact = false, large = false }: { compact?: boolean; large?: boolean }) { return <div className={`brand ${compact ? 'brand-compact' : ''} ${large ? 'brand-large' : ''}`}><div className="brand-mark"><HeartPulse size={compact ? 21 : large ? 40 : 27} /><span /></div>{!compact && <div className="brand-type"><strong>HEALTH<br />SAATHI</strong><small>Your health · Our priority</small></div>}</div> }
function Avatar({ profile }: { profile: Profile }) { return profile.photo ? <img className="avatar" src={profile.photo} alt={profile.name} /> : <div className="avatar avatar-initial">{profile.name.slice(0, 1).toUpperCase()}</div> }
function NavButton({ active, icon: Icon, label, onClick }: { active: boolean; icon: typeof Home; label: string; onClick: () => void }) { return <button className={`rail-link ${active ? 'active' : ''}`} onClick={onClick}><Icon size={18} /><span>{label}</span>{active && <i />}</button> }
function BottomNav({ view, navigate, tr, onAdd }: { view: View; navigate: (v: View) => void; tr: (key: string) => string; onAdd: () => void }) { const item = (key: View, label: string, Icon: typeof Home) => <button key={key} className={view === key ? 'active' : ''} onClick={() => navigate(key)}><Icon size={21} /><span>{label}</span></button>; return <nav className="bottom-nav">{item('home', tr('home'), Home)}{item('records', tr('records'), ClipboardList)}<button className="nav-fab" aria-label="Quick add" onClick={onAdd}><Plus size={30} strokeWidth={2.6} /></button>{item('medicines', tr('medicines'), Pill)}{item('profile', tr('profile'), UserRound)}</nav> }
function QuickSheet({ close, onOpen }: { close: () => void; onOpen: (t: ModalType) => void }) { const items: [ModalType, string, typeof Home][] = [['bp', 'Blood Pressure', HeartPulse], ['sugar', 'Blood Sugar', Droplets], ['weight', 'Weight', Scale], ['water', 'Water', GlassWater], ['medicine', 'Medicine', Pill], ['appointment', 'Appointment', CalendarDays], ['note', 'Note', NotebookPen]]; return <ModalShell title="Quick add" eyebrow="What would you like to record?" close={close}><div className="quick-sheet">{items.map(([type, label, Icon]) => <button key={label} onClick={() => { close(); onOpen(type) }}><Icon size={22} /><span>{label}</span></button>)}</div></ModalShell> }

function Dashboard({ data, tr, currentWater, waterBump, onNavigate, onOpen, onWater, onFavorite }: { data: AppData; tr: (key: string) => string; currentWater: WaterDay; waterBump: number; onNavigate: (v: View) => void; onOpen: (t: ModalType) => void; onWater: (d: number) => void; onFavorite: (key: string) => void }) {
  const tip = data.settings.lang === 'ur' ? 'آج کافی پانی پئیں، دل کو صحت مند رکھیں اور ہر روز متحرک رہیں۔' : 'Drink enough water today, keep your heart healthy and stay active every day.'
  const latestBP = data.bp[0]; const latestSugar = data.sugar[0]
  const quick = [{ key: 'bp', label: tr('bp'), icon: HeartPulse, tone: 'rose', action: () => onOpen('bp') }, { key: 'sugar', label: tr('sugar'), icon: Droplets, tone: 'aqua', action: () => onOpen('sugar') }, { key: 'weight', label: tr('weight'), icon: Scale, tone: 'lime', action: () => onOpen('weight') }, { key: 'water', label: tr('water'), icon: GlassWater, tone: 'blue', action: () => onOpen('water') }, { key: 'medicines', label: tr('medicines'), icon: Pill, tone: 'violet', action: () => onOpen('medicine') }, { key: 'appointments', label: tr('appointments'), icon: CalendarDays, tone: 'gold', action: () => onOpen('appointment') }, { key: 'notes', label: tr('notes'), icon: NotebookPen, tone: 'orange', action: () => onOpen('note') }]
  return <div className="dashboard page-enter">
    <section className="welcome-row"><div><div className="eyebrow"><CloudSun size={15} /> {new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</div><h1>{tr('greeting')}, {data.profile.name.split(' ')[0]} <span className="wave">✦</span></h1><p>{tr('dashboard')}</p></div><button className="profile-chip" onClick={() => onNavigate('profile')}><Avatar profile={data.profile} /><span>My profile</span><ChevronDown size={15} /></button></section>
    <section className="hero-grid"><div className="tip-card glass-card"><div className="tip-glow" /><div className="tip-content"><div className="sticker yellow"><Sparkles size={19} /></div><div><span className="section-kicker">{tr('healthTip')}</span><h3>{tip}</h3><button className="text-link" onClick={() => onOpen('water')}>Make it count <ArrowRight size={14} /></button></div></div><div className="tip-leaf">☘</div></div><div className="heart-summary glass-card"><div className="heart-summary-top"><span className="section-kicker">Your wellness pulse</span><span className="live-dot"><i /> Live</span></div><div className="heart-number"><strong>{latestBP?.pulse || 72}</strong><span>bpm<br /><small>resting pulse</small></span></div><ECG /><div className="summary-foot"><span><TrendingUp size={14} /> Steady today</span><button onClick={() => onNavigate('records')}>View history <ChevronRight size={14} /></button></div></div></section>
    <section className="section-block"><div className="section-heading"><div><span className="section-kicker">{tr('quickAdd')}</span><h2>Keep your rhythm going</h2></div><span className="muted-label">Tap to record</span></div><div className="quick-grid">{quick.map(item => <button className="quick-card" key={item.key} onClick={item.action}><span className={`quick-icon ${item.tone}`}><item.icon size={20} /></span><span>{item.label}</span><Plus size={14} className="quick-plus" /></button>)}</div></section>
    <section className="snapshot-grid"><MetricCard label={tr('bp')} value={latestBP ? `${latestBP.systolic}/${latestBP.diastolic}` : '—'} unit="mmHg" icon={HeartPulse} tone="rose" trend="Latest reading" onClick={() => onNavigate('records')} favorite={data.favorites.includes('bp')} onFavorite={() => onFavorite('bp')} /><MetricCard label={tr('sugar')} value={latestSugar ? String(latestSugar.value) : '—'} unit={latestSugar?.unit || 'mg/dL'} icon={Droplets} tone="aqua" trend="After meal" onClick={() => onNavigate('records')} favorite={data.favorites.includes('sugar')} onFavorite={() => onFavorite('sugar')} /><WaterCard water={currentWater} onWater={onWater} bump={waterBump} favorite={data.favorites.includes('water')} onFavorite={() => onFavorite('water')} /></section>
    <section className="lower-grid"><div className="glass-card activity-card"><div className="section-heading"><div><span className="section-kicker">{tr('recent')}</span><h2>Little wins add up</h2></div><button className="text-link" onClick={() => onNavigate('records')}>{tr('seeAll')} <ArrowRight size={14} /></button></div><div className="activity-list"><ActivityRow icon={Pill} tone="violet" title={data.medicines[0]?.name || 'No medicine'} sub={data.medicines[0] ? `${data.medicines[0].dosage} · ${data.medicines[0].reminder}` : 'Add your first medicine'} action={() => onNavigate('medicines')} /><ActivityRow icon={CalendarDays} tone="gold" title={data.appointments[0]?.doctor || 'No appointment'} sub={data.appointments[0] ? `${shortDate(data.appointments[0].date)} · ${data.appointments[0].time}` : 'Plan a doctor visit'} action={() => onNavigate('appointments')} /><ActivityRow icon={NotebookPen} tone="orange" title={data.notes[0]?.title || 'Your health notes'} sub={data.notes[0]?.body || 'Capture a thought for later'} action={() => onNavigate('notes')} /></div></div><div className="glass-card habit-card"><div className="habit-orb"><Leaf size={24} /></div><span className="section-kicker">Gentle reminder</span><h3>Move a little, breathe deeply.</h3><p>Small moments of movement can make your day feel lighter.</p><div className="habit-footer"><span><Zap size={14} /> Wellness note</span><button onClick={() => onOpen('note')}>Save note <ArrowRight size={13} /></button></div></div></section>
  </div>
}
function ECG() { return <div className="ecg"><svg viewBox="0 0 600 80" preserveAspectRatio="none"><path d="M0,43 H90 C102,43 108,41 117,43 L135,43 L150,20 L165,62 L182,43 H255 C268,43 270,39 281,43 H345 L360,16 L375,68 L390,43 H470 C490,43 502,44 520,43 H600" /></svg></div> }
function MetricCard({ label, value, unit, icon: Icon, tone, trend, onClick, favorite, onFavorite }: { label: string; value: string; unit: string; icon: typeof HeartPulse; tone: string; trend: string; onClick: () => void; favorite: boolean; onFavorite: () => void }) { return <div className="metric-card glass-card" onClick={onClick}><div className="metric-top"><span className={`quick-icon ${tone}`}><Icon size={18} /></span><button className={`favorite-btn ${favorite ? 'is-favorite' : ''}`} onClick={(e) => { e.stopPropagation(); onFavorite() }} aria-label="Toggle favorite"><Heart size={15} fill={favorite ? 'currentColor' : 'none'} /></button></div><span className="metric-label">{label}</span><div className="metric-value"><strong>{value}</strong><span>{unit}</span></div><span className="metric-trend"><TrendingUp size={13} /> {trend}</span></div> }
function WaterCard({ water, onWater, bump, favorite, onFavorite }: { water: WaterDay; onWater: (d: number) => void; bump: number; favorite: boolean; onFavorite: () => void }) { const pct = Math.min(100, Math.round((water.glasses / water.goal) * 100)); return <div className={`water-card glass-card ${bump ? 'water-bump' : ''}`}><div className="metric-top"><span className="quick-icon blue"><GlassWater size={18} /></span><button className={`favorite-btn ${favorite ? 'is-favorite' : ''}`} onClick={onFavorite} aria-label="Toggle favorite"><Heart size={15} fill={favorite ? 'currentColor' : 'none'} /></button></div><div className="water-head"><div><span className="metric-label">Water intake</span><div className="metric-value"><strong>{water.glasses}</strong><span>/ {water.goal} glasses</span></div></div><div className="water-drop"><Droplets size={20} /></div></div><div className="water-progress"><span style={{ width: `${pct}%` }} /></div><div className="water-actions"><small>{pct}% of daily goal</small><div><button onClick={() => onWater(-1)} aria-label="Remove water"><span>−</span></button><button onClick={() => onWater(1)} aria-label="Add water"><span>+</span></button></div></div></div> }
function ActivityRow({ icon: Icon, tone, title, sub, action }: { icon: typeof Pill; tone: string; title: string; sub: string; action: () => void }) { return <button className="activity-row" onClick={action}><span className={`quick-icon ${tone}`}><Icon size={17} /></span><span className="activity-copy"><strong>{title}</strong><small>{sub}</small></span><ChevronRight size={16} /></button> }

function PageHeader({ eyebrow, title, description, action, actionLabel }: { eyebrow?: string; title: string; description?: string; action?: () => void; actionLabel?: string }) { return <div className="page-header"><div><span className="section-kicker">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action && <button className="primary-btn" onClick={action}><Plus size={17} /> {actionLabel || 'Add new'}</button>}</div> }
function RecordsPage({ records, filter, setFilter, onNavigate, onOpen }: { records: RecordItem[]; filter: string; setFilter: (x: string) => void; onNavigate: (v: View) => void; onOpen: (t: ModalType) => void }) { const filters = ['All', 'BP', 'Sugar', 'Weight', 'Water', 'Appointment', 'Note']; return <div className="page-enter"><PageHeader eyebrow="Your timeline" title="Health records" description="A clear, gentle view of your everyday health story." action={() => onOpen('bp')} actionLabel="Add record" /><div className="filter-row">{filters.map(x => <button key={x} className={filter === x ? 'active' : ''} onClick={() => setFilter(x)}>{x === 'All' ? 'All records' : x}</button>)}</div><div className="records-list">{records.length ? records.map(record => <RecordCard key={`${record.kind}-${record.id}`} record={record} />) : <EmptyState title="No records in this view" text="Start with a small reading and build your personal health story." action={() => onOpen('bp')} />}</div><button className="soft-action" onClick={() => onNavigate('home')}><Home size={16} /> Back to dashboard</button></div> }
function RecordCard({ record }: { record: RecordItem }) { const Icon = record.kind === 'BP' ? HeartPulse : record.kind === 'Sugar' ? Droplets : record.kind === 'Weight' ? Scale : record.kind === 'Water' ? GlassWater : record.kind === 'Appointment' ? CalendarDays : NotebookPen; const tone = record.kind === 'BP' ? 'rose' : record.kind === 'Sugar' ? 'aqua' : record.kind === 'Water' ? 'blue' : record.kind === 'Weight' ? 'lime' : record.kind === 'Appointment' ? 'gold' : 'orange'; return <div className="record-row glass-card"><span className={`quick-icon ${tone}`}><Icon size={18} /></span><div className="record-main"><strong>{record.label}</strong><span>{record.note || record.kind}</span></div><div className="record-value"><strong>{record.value}</strong><small>{prettyDate(record.date)}{record.time ? ` · ${record.time}` : ''}</small></div><ChevronRight size={16} /></div> }
function EmptyState({ title, text, action, actionLabel = 'Add first record' }: { title: string; text: string; action: () => void; actionLabel?: string }) { return <div className="empty-state glass-card"><div className="empty-illustration"><HeartPulse size={28} /></div><h3>{title}</h3><p>{text}</p><button className="primary-btn" onClick={action}><Plus size={16} /> {actionLabel}</button></div> }

function MedicinesPage({ data, setData, onOpen, notify, onFavorite }: { data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; onOpen: (t: ModalType, id?: string) => void; notify: (x: string) => void; onFavorite: (x: string) => void }) { return <div className="page-enter"><PageHeader eyebrow="Care, on time" title="Medicines" description="Keep every dose, note and reminder close at hand." action={() => onOpen('medicine')} actionLabel="Add medicine" /><div className="medicine-banner glass-card"><div className="banner-icon"><Pill size={24} /></div><div><strong>Your medicine rhythm</strong><p>{data.medicines.filter(x => x.taken).length} of {data.medicines.length} marked taken today</p></div><div className="banner-progress"><span style={{ width: `${data.medicines.length ? (data.medicines.filter(x => x.taken).length / data.medicines.length) * 100 : 0}%` }} /></div></div><div className="list-heading"><h2>Today’s plan</h2><button className={`favorite-btn ${data.favorites.includes('medicines') ? 'is-favorite' : ''}`} onClick={() => onFavorite('medicines')}><Heart size={17} fill={data.favorites.includes('medicines') ? 'currentColor' : 'none'} /> Favorite</button></div><div className="medicine-list">{data.medicines.length ? data.medicines.map(med => <MedicineRow key={med.id} medicine={med} onOpen={onOpen} setData={setData} notify={notify} />) : <EmptyState title="No medicines yet" text="Add a medicine or scan its pack to create a reminder." action={() => onOpen('medicine')} actionLabel="Add medicine" />}</div></div> }
function MedicineRow({ medicine, onOpen, setData, notify }: { medicine: Medicine; onOpen: (t: ModalType, id?: string) => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { return <div className={`medicine-row glass-card ${medicine.taken ? 'taken-row' : ''}`}><div className="medicine-photo">{medicine.image ? <img src={medicine.image} alt={medicine.name} /> : <Pill size={22} />}</div><div className="medicine-copy"><div className="medicine-title"><strong>{medicine.name}</strong>{medicine.taken && <span className="taken-badge"><Check size={12} /> Taken</span>}</div><span>{medicine.dosage || 'Dosage to confirm'}</span><small>{medicine.instructions || 'Add instructions'} · <Bell size={12} /> {medicine.reminder || 'No time'} · {medicine.repeat}</small></div><div className="medicine-actions"><button className="icon-btn" onClick={() => { setData(prev => ({ ...prev, medicines: prev.medicines.map(x => x.id === medicine.id ? { ...x, taken: !x.taken } : x) })); notify(medicine.taken ? 'Marked as upcoming' : 'Marked as taken') }} aria-label="Toggle taken"><Check size={17} /></button><button className="icon-btn" onClick={() => onOpen('medicine', medicine.id)} aria-label="Edit medicine"><Edit3 size={16} /></button><button className="icon-btn danger" onClick={() => { if (window.confirm('Delete this medicine?')) { setData(prev => ({ ...prev, medicines: prev.medicines.filter(x => x.id !== medicine.id) })); notify('Medicine deleted') } }} aria-label="Delete medicine"><Trash2 size={16} /></button></div></div> }

function AppointmentsPage({ data, setData, onOpen, notify }: { data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; onOpen: (t: ModalType, id?: string) => void; notify: (x: string) => void }) { return <div className="page-enter"><PageHeader eyebrow="Care calendar" title="Appointments" description="Keep upcoming care visits visible and easy to prepare for." action={() => onOpen('appointment')} actionLabel="Add appointment" /><div className="appointment-list">{data.appointments.length ? data.appointments.map(apt => <div className="appointment-row glass-card" key={apt.id}><div className="date-tile"><strong>{new Date(`${apt.date}T12:00:00`).getDate()}</strong><span>{new Date(`${apt.date}T12:00:00`).toLocaleDateString(undefined, { month: 'short' })}</span></div><div className="appointment-copy"><strong>{apt.doctor}</strong><span>{apt.specialty}</span><small><CalendarDays size={13} /> {apt.time} · {apt.reason}</small></div><div className="row-actions"><button className="icon-btn" onClick={() => onOpen('appointment', apt.id)}><Edit3 size={16} /></button><button className="icon-btn danger" onClick={() => { if (window.confirm('Delete this appointment?')) { setData(prev => ({ ...prev, appointments: prev.appointments.filter(x => x.id !== apt.id) })); notify('Appointment deleted') } }}><Trash2 size={16} /></button></div></div>) : <EmptyState title="No appointments yet" text="Keep your next check-in close by." action={() => onOpen('appointment')} actionLabel="Add appointment" />}</div></div> }
function NotesPage({ data, setData, onOpen, notify }: { data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; onOpen: (t: ModalType, id?: string) => void; notify: (x: string) => void }) { return <div className="page-enter"><PageHeader eyebrow="Personal journal" title="Notes" description="Capture observations, plans and questions for your next visit." action={() => onOpen('note')} actionLabel="Add note" /><div className="notes-grid">{data.notes.length ? data.notes.map(note => <div className="note-card glass-card" key={note.id}><div className="note-top"><span className="note-pin">{note.category.slice(0, 1)}</span><span>{note.category}</span><div className="row-actions"><button className="icon-btn" onClick={() => onOpen('note', note.id)}><Edit3 size={15} /></button><button className="icon-btn danger" onClick={() => { if (window.confirm('Delete this note?')) { setData(prev => ({ ...prev, notes: prev.notes.filter(x => x.id !== note.id) })); notify('Note deleted') } }}><Trash2 size={15} /></button></div></div><h3>{note.title}</h3><p>{note.body}</p><small>{prettyDate(note.date)} · {note.time}</small></div>) : <EmptyState title="Your notes are waiting" text="Save a thought, symptom or question whenever it comes to you." action={() => onOpen('note')} actionLabel="Add note" />}</div></div> }
function FavoritesPage({ favorites, onFavorite, onNavigate }: { favorites: string[]; onFavorite: (x: string) => void; onNavigate: (x: View) => void }) { const catalog = [{ key: 'bp', title: 'Blood pressure', desc: 'Record and review readings', icon: HeartPulse, view: 'records' as View, tone: 'rose' }, { key: 'sugar', title: 'Blood sugar', desc: 'Keep glucose trends visible', icon: Droplets, view: 'records' as View, tone: 'aqua' }, { key: 'weight', title: 'Weight', desc: 'Track your progress gently', icon: Scale, view: 'records' as View, tone: 'lime' }, { key: 'water', title: 'Water', desc: 'Stay close to your daily goal', icon: GlassWater, view: 'home' as View, tone: 'blue' }, { key: 'medicines', title: 'Medicines', desc: 'Keep reminders in reach', icon: Pill, view: 'medicines' as View, tone: 'violet' }]; const shown = catalog.filter(x => favorites.includes(x.key)); return <div className="page-enter"><PageHeader eyebrow="Your shortcuts" title="Favorites" description="Keep the parts of Health Saathi you reach for most." /><div className="favorite-grid">{shown.length ? shown.map(item => <button className="favorite-card glass-card" key={item.key} onClick={() => onNavigate(item.view)}><span className={`quick-icon ${item.tone}`}><item.icon size={22} /></span><span><strong>{item.title}</strong><small>{item.desc}</small></span><button className="favorite-remove" onClick={(e) => { e.stopPropagation(); onFavorite(item.key) }} aria-label={`Remove ${item.title}`}><X size={15} /></button><ChevronRight size={16} /></button>) : <EmptyState title="Nothing pinned yet" text="Favorite the trackers you want close at hand." action={() => onNavigate('home')} actionLabel="Explore dashboard" />}</div></div> }

function ProfilePage({ data, setData, onOpen, notify }: { data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; onOpen: (t: ModalType) => void; notify: (x: string) => void }) { return <div className="page-enter"><PageHeader eyebrow="Your health space" title="Profile" description="A few details help Health Saathi feel more personal." action={() => onOpen('profile')} actionLabel="Edit profile" /><div className="profile-hero glass-card"><div className="profile-large"><Avatar profile={data.profile} /><button onClick={() => onOpen('profile')} aria-label="Change profile photo"><Camera size={15} /></button></div><div><h2>{data.profile.name}</h2><p>{data.profile.healthInfo || 'Add a little health context'}</p><div className="profile-pills"><span><UserRound size={13} /> {data.profile.age || '—'} years</span><span><HeartPulse size={13} /> {data.profile.bloodGroup || 'Blood group —'}</span></div></div></div><div className="profile-info-grid"><InfoTile icon={UserRound} label="Name" value={data.profile.name} /><InfoTile icon={CalendarDays} label="Age" value={data.profile.age ? `${data.profile.age} years` : 'Not added'} /><InfoTile icon={HeartPulse} label="Blood group" value={data.profile.bloodGroup || 'Not added'} /><InfoTile icon={ShieldCheck} label="Privacy" value="Stored on this device" /></div><div className="privacy-callout"><LockKeyhole size={18} /><div><strong>Your health data stays close.</strong><p>Health Saathi stores your personal entries locally in this browser. Export a backup whenever you want.</p></div></div></div> }
function InfoTile({ icon: Icon, label, value }: { icon: typeof UserRound; label: string; value: string }) { return <div className="info-tile glass-card"><Icon size={17} /><small>{label}</small><strong>{value}</strong></div> }

function SettingsPage({ data, setData, onOpen, onInstall, installReady, onNotify, onShare, onExport, onImport, notify }: { data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; onOpen: (t: ModalType) => void; onInstall: () => void; installReady: boolean; onNotify: () => void; onShare: () => void; onExport: () => void; onImport: (e: ChangeEvent<HTMLInputElement>) => void; notify: (x: string) => void }) { const [showPrivacy, setShowPrivacy] = useState(false); const changeTheme = (theme: Theme) => { setData(prev => ({ ...prev, settings: { ...prev.settings, theme } })); notify(`${theme[0].toUpperCase()}${theme.slice(1)} theme applied`) }; return <div className="page-enter"><PageHeader eyebrow="Make it yours" title="Settings" description="Quiet controls for your space, your data and your day." /><div className="settings-list"><SettingRow icon={Languages} title="Language" sub={data.settings.lang === 'en' ? 'English' : 'اردو'} onClick={() => onOpen('language')} /><SettingRow icon={data.settings.theme === 'dark' ? Moon : Sun} title="Theme / appearance" sub={data.settings.theme === 'system' ? 'System default' : data.settings.theme === 'dark' ? 'Dark mode' : 'Light mode'} onClick={() => changeTheme(data.settings.theme === 'light' ? 'dark' : data.settings.theme === 'dark' ? 'system' : 'light')} /><SettingRow icon={Bell} title="Notifications" sub={data.settings.notifications ? 'Medicine reminders enabled' : 'Set up reminders'} onClick={onNotify} /><SettingRow icon={ExternalLink} title="Install app" sub={installReady ? 'Ready to install' : 'Add to your home screen'} onClick={onInstall} />
    <div className="settings-divider" /><div className="settings-section-label">Your data</div><SettingRow icon={FileDown} title="Data / backup" sub="Export a private JSON backup" onClick={onExport} /><label className="setting-row" htmlFor="restore-backup"><span className="setting-icon aqua"><FileUp size={18} /></span><span className="setting-copy"><strong>Restore backup</strong><small>Import a Health Saathi JSON file</small></span><ChevronRight size={17} /><input id="restore-backup" type="file" accept="application/json,.json" onChange={onImport} hidden /></label><SettingRow icon={LockKeyhole} title="Privacy" sub="Local-first, private by design" onClick={() => setShowPrivacy(!showPrivacy)} />{showPrivacy && <div className="privacy-panel"><ShieldCheck size={18} /><span>We do not send your health entries to a server in this version. Your browser storage and downloaded backups are under your control.</span></div>}
    <div className="settings-divider" /><div className="settings-section-label">About and sharing</div><SettingRow icon={Share2} title="Share app" sub="Send Health Saathi to someone you care about" onClick={onShare} /><SettingRow icon={Info} title="About Health Saathi" sub="Version 1.0 · Developed by Muhammad Usman Channa" onClick={() => onOpen('about')} /></div><div className="settings-footer"><Brand compact={false} /><p>Designed with care for everyday wellness.</p><small>Health Saathi is a personal tracking tool, not a medical diagnosis service.</small></div></div> }
function SettingRow({ icon: Icon, title, sub, onClick }: { icon: typeof Bell; title: string; sub: string; onClick: () => void }) { return <button className="setting-row" onClick={onClick}><span className="setting-icon"><Icon size={18} /></span><span className="setting-copy"><strong>{title}</strong><small>{sub}</small></span><ChevronRight size={17} /></button> }

function SearchOverlay({ query, setQuery, results, onClose, onNavigate }: { query: string; setQuery: (x: string) => void; results: { title: string; sub: string; target: View; icon: typeof Pill }[]; onClose: () => void; onNavigate: (v: View) => void }) { const inputRef = useRef<HTMLInputElement>(null); useEffect(() => { inputRef.current?.focus(); const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose() }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [onClose]); return <div className="overlay-backdrop" onClick={onClose}><div className="search-panel" onClick={e => e.stopPropagation()}><div className="search-panel-input"><Search size={20} /><input ref={inputRef} value={query} onChange={e => setQuery(e.target.value)} placeholder="Search health, medicines, records..." /><button onClick={onClose}><X size={18} /></button></div>{query ? <div className="search-results">{results.length ? results.map((item, i) => <button key={`${item.title}-${i}`} onClick={() => { onNavigate(item.target); onClose() }}><span className="quick-icon aqua"><item.icon size={17} /></span><span><strong>{item.title}</strong><small>{item.sub}</small></span><ArrowRight size={16} /></button>) : <div className="search-empty"><Search size={24} /><p>No matches yet. Try “water”, “medicine” or “blood”.</p></div>}</div> : <div className="suggestions"><span>Quick suggestions</span><div>{['Blood pressure', 'Sugar', 'Medicines', 'Appointments', 'Notes'].map(x => <button key={x} onClick={() => setQuery(x)}><Search size={14} />{x}</button>)}</div></div>}<div className="search-hint"><kbd>Esc</kbd> to close <span>Private on this device</span></div></div></div> }

function ModalShell({ title, eyebrow, children, close }: { title: string; eyebrow?: string; children: ReactNode; close: () => void }) { return <div className="modal-backdrop" onClick={close}><div className="modal-card" onClick={e => e.stopPropagation()}><div className="modal-header"><div><span className="section-kicker">{eyebrow}</span><h2>{title}</h2></div><button className="icon-btn" onClick={close} aria-label="Close"><X size={19} /></button></div>{children}</div></div> }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function ModalRouter({ modal, data, setData, close, notify, onNotify }: { modal: { type: ModalType; editId?: string }; data: AppData; setData: React.Dispatch<React.SetStateAction<AppData>>; close: () => void; notify: (x: string) => void; onNotify: () => void }) {
  if (modal.type === 'bp') return <BPModal existing={data.bp.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} />
  if (modal.type === 'sugar') return <SugarModal existing={data.sugar.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} />
  if (modal.type === 'weight') return <WeightModal existing={data.weight.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} />
  if (modal.type === 'water') return <WaterModal current={data.water.find(x => x.date === today())} close={close} setData={setData} notify={notify} />
  if (modal.type === 'medicine') return <MedicineModal existing={data.medicines.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} onNotify={onNotify} />
  if (modal.type === 'appointment') return <AppointmentModal existing={data.appointments.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} />
  if (modal.type === 'note') return <NoteModal existing={data.notes.find(x => x.id === modal.editId)} close={close} setData={setData} notify={notify} />
  if (modal.type === 'profile') return <ProfileModal profile={data.profile} close={close} setData={setData} notify={notify} />
  if (modal.type === 'language') return <LanguageModal current={data.settings.lang} close={close} setData={setData} />
  if (modal.type === 'about') return <ModalShell title="About Health Saathi" eyebrow="Made with care" close={close}><div className="about-card"><div className="about-logo"><Brand compact={false} /></div><HeartPulse size={30} /><p>Health Saathi brings your everyday health notes, readings, water, medicines and appointments into one calm, private space.</p><strong>Developed by Muhammad Usman Channa Channa</strong><small>Version 1.0 · Local-first PWA</small></div></ModalShell>
  return null
}

function FormActions({ close, label = 'Save record' }: { close: () => void; label?: string }) { return <div className="form-actions"><button type="button" className="ghost-btn" onClick={close}>Cancel</button><button type="submit" className="primary-btn"><Check size={16} /> {label}</button></div> }
function BPModal({ existing, close, setData, notify }: { existing?: BPRecord; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ systolic: String(existing?.systolic || 120), diastolic: String(existing?.diastolic || 80), pulse: String(existing?.pulse || 72), date: existing?.date || today(), time: existing?.time || nowTime(), note: existing?.note || '' }); const submit = (e: FormEvent) => { e.preventDefault(); if (!form.systolic || !form.diastolic || !form.pulse) return; const item = { id: existing?.id || id(), systolic: Number(form.systolic), diastolic: Number(form.diastolic), pulse: Number(form.pulse), date: form.date, time: form.time, note: form.note }; setData(prev => ({ ...prev, bp: existing ? prev.bp.map(x => x.id === existing.id ? item : x) : [item, ...prev.bp] })); notify(existing ? 'Blood pressure updated' : 'Blood pressure saved'); close() }; return <ModalShell title="Blood pressure" eyebrow="Add a calm check-in" close={close}><form onSubmit={submit} className="form-grid"><div className="form-intro"><span className="quick-icon rose"><HeartPulse size={20} /></span><p>Record a reading for your personal history. This tool does not diagnose conditions.</p></div><Field label="Systolic (mmHg)"><input required type="number" min="0" value={form.systolic} onChange={e => setForm({ ...form, systolic: e.target.value })} /></Field><Field label="Diastolic (mmHg)"><input required type="number" min="0" value={form.diastolic} onChange={e => setForm({ ...form, diastolic: e.target.value })} /></Field><Field label="Pulse (bpm)"><input required type="number" min="0" value={form.pulse} onChange={e => setForm({ ...form, pulse: e.target.value })} /></Field><Field label="Date"><input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></Field><Field label="Time"><input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} /></Field><Field label="Notes (optional)"><textarea rows={3} placeholder="How were you feeling?" value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></Field><FormActions close={close} label={existing ? 'Update reading' : 'Save reading'} /></form></ModalShell> }
function SugarModal({ existing, close, setData, notify }: { existing?: SugarRecord; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ value: String(existing?.value || 98), unit: existing?.unit || 'mg/dL', meal: existing?.meal || 'After meal', date: existing?.date || today(), time: existing?.time || nowTime(), note: existing?.note || '' }); const submit = (e: FormEvent) => { e.preventDefault(); const item = { id: existing?.id || id(), value: Number(form.value), unit: form.unit, meal: form.meal, date: form.date, time: form.time, note: form.note }; setData(prev => ({ ...prev, sugar: existing ? prev.sugar.map(x => x.id === existing.id ? item : x) : [item, ...prev.sugar] })); notify('Sugar reading saved'); close() }; return <ModalShell title="Blood sugar" eyebrow="Glucose check-in" close={close}><form onSubmit={submit} className="form-grid"><div className="form-intro"><span className="quick-icon aqua"><Droplets size={20} /></span><p>Keep the unit and meal context with every reading so your history stays useful.</p></div><Field label="Glucose value"><input required type="number" min="0" value={form.value} onChange={e => setForm({ ...form, value: e.target.value })} /></Field><Field label="Unit"><select value={form.unit} onChange={e => setForm({ ...form, unit: e.target.value })}><option>mg/dL</option><option>mmol/L</option></select></Field><Field label="Meal context"><select value={form.meal} onChange={e => setForm({ ...form, meal: e.target.value })}><option>Before meal</option><option>After meal</option><option>Fasting</option></select></Field><Field label="Date"><input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></Field><Field label="Time"><input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} /></Field><Field label="Notes (optional)"><textarea rows={3} value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></Field><FormActions close={close} label={existing ? 'Update reading' : 'Save reading'} /></form></ModalShell> }
function WeightModal({ existing, close, setData, notify }: { existing?: WeightRecord; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ value: String(existing?.value || 68.5), unit: existing?.unit || 'kg', date: existing?.date || today(), time: existing?.time || nowTime(), note: existing?.note || '' }); const submit = (e: FormEvent) => { e.preventDefault(); const item = { id: existing?.id || id(), value: Number(form.value), unit: form.unit, date: form.date, time: form.time, note: form.note }; setData(prev => ({ ...prev, weight: existing ? prev.weight.map(x => x.id === existing.id ? item : x) : [item, ...prev.weight] })); notify('Weight saved'); close() }; return <ModalShell title="Weight" eyebrow="Track your progress" close={close}><form onSubmit={submit} className="form-grid"><div className="form-intro"><span className="quick-icon lime"><Scale size={20} /></span><p>Consistency matters more than a single number. Keep your notes kind and practical.</p></div><Field label="Weight"><input required type="number" min="0" step="0.1" value={form.value} onChange={e => setForm({ ...form, value: e.target.value })} /></Field><Field label="Unit"><select value={form.unit} onChange={e => setForm({ ...form, unit: e.target.value })}><option>kg</option><option>lb</option></select></Field><Field label="Date"><input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></Field><Field label="Time"><input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} /></Field><Field label="Notes (optional)"><textarea rows={3} value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></Field><FormActions close={close} label={existing ? 'Update weight' : 'Save weight'} /></form></ModalShell> }
function WaterModal({ current, close, setData, notify }: { current?: WaterDay; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ glasses: String(current?.glasses || 0), goal: String(current?.goal || 8) }); const submit = (e: FormEvent) => { e.preventDefault(); const item = { date: today(), glasses: Number(form.glasses), goal: Number(form.goal) }; setData(prev => ({ ...prev, water: [...prev.water.filter(x => x.date !== today()), item] })); notify('Water goal updated'); close() }; return <ModalShell title="Water tracker" eyebrow="A little more hydration" close={close}><form onSubmit={submit} className="form-grid"><div className="water-modal-visual"><Droplets size={34} /><strong>{form.glasses} <small>glasses today</small></strong><span style={{ width: `${Math.min(100, (Number(form.glasses) / Number(form.goal || 1)) * 100)}%` }} /></div><Field label="Current glasses"><input type="number" min="0" value={form.glasses} onChange={e => setForm({ ...form, glasses: e.target.value })} /></Field><Field label="Daily goal"><input type="number" min="1" value={form.goal} onChange={e => setForm({ ...form, goal: e.target.value })} /></Field><FormActions close={close} label="Save water" /></form></ModalShell> }

function MedicineModal({ existing, close, setData, notify, onNotify }: { existing?: Medicine; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void; onNotify: () => void }) { const [form, setForm] = useState({ name: existing?.name || '', dosage: existing?.dosage || '', instructions: existing?.instructions || '', note: existing?.note || '', reminder: existing?.reminder || '08:00', repeat: existing?.repeat || 'Daily', image: existing?.image || '' }); const [scanNote, setScanNote] = useState('')
  const processImage = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const image = await readFile(file); const base = file.name.replace(/\.[^/.]+$/, '').replace(/[-_]/g, ' '); const dose = file.name.match(/(\d+(?:\.\d+)?)\s*(mg|mcg|g|ml)/i)?.[0] || ''; setForm(prev => ({ ...prev, image, name: prev.name || base, dosage: prev.dosage || dose })); setScanNote(dose || base ? 'Review the prefilled details before saving — smart capture is best-effort.' : 'Image attached. Add the details you want to remember.'); event.target.value = '' }
  const submit = (e: FormEvent) => { e.preventDefault(); if (!form.name.trim()) { setScanNote('Please add the medicine name before saving.'); return } const item: Medicine = { id: existing?.id || id(), name: form.name.trim(), dosage: form.dosage, instructions: form.instructions, note: form.note, reminder: form.reminder, repeat: form.repeat, image: form.image, taken: existing?.taken || false, createdAt: existing?.createdAt || today() }; setData(prev => ({ ...prev, medicines: existing ? prev.medicines.map(x => x.id === existing.id ? item : x) : [item, ...prev.medicines] })); notify(existing ? 'Medicine updated' : 'Medicine added'); close() }
  return <ModalShell title={existing ? 'Edit medicine' : 'Add medicine'} eyebrow="Keep care on time" close={close}><form onSubmit={submit} className="form-grid medicine-form"><div className="medicine-capture"><div className="capture-preview">{form.image ? <img src={form.image} alt="Medicine preview" /> : <Pill size={28} />}</div><div><strong>Smart capture</strong><p>Take a photo or choose the medicine pack. We’ll prefill recognizable details for your review.</p><div className="capture-actions"><label className="soft-action"><Camera size={15} /> Camera<input type="file" accept="image/*" capture="environment" onChange={processImage} hidden /></label><label className="soft-action"><ExternalLink size={15} /> Gallery<input type="file" accept="image/*" onChange={processImage} hidden /></label></div></div></div>{scanNote && <div className="scan-note"><Sparkles size={15} />{scanNote}</div>}<Field label="Medicine name"><input required placeholder="e.g. Paracetamol" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></Field><Field label="Dosage / strength"><input placeholder="e.g. 500 mg" value={form.dosage} onChange={e => setForm({ ...form, dosage: e.target.value })} /></Field><Field label="Dosage instructions"><input placeholder="1 tablet after food" value={form.instructions} onChange={e => setForm({ ...form, instructions: e.target.value })} /></Field><div className="form-two"><Field label="Reminder time"><input type="time" value={form.reminder} onChange={e => setForm({ ...form, reminder: e.target.value })} /></Field><Field label="Repeat"><select value={form.repeat} onChange={e => setForm({ ...form, repeat: e.target.value })}><option>Daily</option><option>Weekly</option><option>Weekdays</option><option>As needed</option></select></Field></div><Field label="Notes (optional)"><textarea rows={2} placeholder="Anything useful to remember" value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></Field><button type="button" className="notification-prompt" onClick={onNotify}><Bell size={16} /> Enable browser reminder permission</button><FormActions close={close} label={existing ? 'Update medicine' : 'Save medicine'} /></form></ModalShell> }
function AppointmentModal({ existing, close, setData, notify }: { existing?: Appointment; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ doctor: existing?.doctor || '', specialty: existing?.specialty || '', date: existing?.date || today(), time: existing?.time || '10:00', reason: existing?.reason || '', note: existing?.note || '' }); const submit = (e: FormEvent) => { e.preventDefault(); const item = { id: existing?.id || id(), ...form }; setData(prev => ({ ...prev, appointments: existing ? prev.appointments.map(x => x.id === existing.id ? item : x) : [item, ...prev.appointments] })); notify(existing ? 'Appointment updated' : 'Appointment added'); close() }; return <ModalShell title={existing ? 'Edit appointment' : 'Add appointment'} eyebrow="Care calendar" close={close}><form onSubmit={submit} className="form-grid"><Field label="Doctor name"><input required placeholder="Dr. Ali Khan" value={form.doctor} onChange={e => setForm({ ...form, doctor: e.target.value })} /></Field><Field label="Specialty"><input placeholder="General physician" value={form.specialty} onChange={e => setForm({ ...form, specialty: e.target.value })} /></Field><div className="form-two"><Field label="Date"><input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></Field><Field label="Time"><input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} /></Field></div><Field label="Reason"><input placeholder="Routine checkup" value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} /></Field><Field label="Notes (optional)"><textarea rows={3} value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} /></Field><FormActions close={close} label={existing ? 'Update appointment' : 'Save appointment'} /></form></ModalShell> }
function NoteModal({ existing, close, setData, notify }: { existing?: HealthNote; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState({ title: existing?.title || '', body: existing?.body || '', category: existing?.category || 'General' }); const submit = (e: FormEvent) => { e.preventDefault(); const item = { id: existing?.id || id(), title: form.title || 'Untitled note', body: form.body, category: form.category, date: existing?.date || today(), time: existing?.time || nowTime() }; setData(prev => ({ ...prev, notes: existing ? prev.notes.map(x => x.id === existing.id ? item : x) : [item, ...prev.notes] })); notify(existing ? 'Note updated' : 'Note saved'); close() }; return <ModalShell title={existing ? 'Edit note' : 'Add note'} eyebrow="Personal journal" close={close}><form onSubmit={submit} className="form-grid"><Field label="Title"><input placeholder="Workout plan" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></Field><Field label="Category"><select value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>{['General', 'Diet', 'Exercise', 'Doctor', 'Medicine', 'Symptoms / observations'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Your note"><textarea required rows={5} placeholder="Write something useful for your future self..." value={form.body} onChange={e => setForm({ ...form, body: e.target.value })} /></Field><FormActions close={close} label={existing ? 'Update note' : 'Save note'} /></form></ModalShell> }
function ProfileModal({ profile, close, setData, notify }: { profile: Profile; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>>; notify: (x: string) => void }) { const [form, setForm] = useState(profile); const file = async (event: ChangeEvent<HTMLInputElement>) => { const selected = event.target.files?.[0]; if (selected) setForm({ ...form, photo: await readFile(selected) }) }; const submit = (e: FormEvent) => { e.preventDefault(); setData(prev => ({ ...prev, profile: form })); notify('Profile updated'); close() }; return <ModalShell title="Edit profile" eyebrow="Your health space" close={close}><form onSubmit={submit} className="form-grid"><div className="profile-edit-photo"><Avatar profile={form} /><label className="soft-action"><Camera size={15} /> Choose photo<input type="file" accept="image/*" onChange={file} hidden /></label></div><Field label="Name"><input required value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></Field><div className="form-two"><Field label="Age"><input type="number" min="0" value={form.age} onChange={e => setForm({ ...form, age: e.target.value })} /></Field><Field label="Blood group"><select value={form.bloodGroup} onChange={e => setForm({ ...form, bloodGroup: e.target.value })}><option>O+</option><option>O−</option><option>A+</option><option>A−</option><option>B+</option><option>B−</option><option>AB+</option><option>AB−</option></select></Field></div><Field label="Basic health information"><textarea rows={3} placeholder="Allergies, goals or useful context" value={form.healthInfo} onChange={e => setForm({ ...form, healthInfo: e.target.value })} /></Field><FormActions close={close} label="Save profile" /></form></ModalShell> }
function LanguageModal({ current, close, setData }: { current: Lang; close: () => void; setData: React.Dispatch<React.SetStateAction<AppData>> }) { const [choice, setChoice] = useState<Lang>(current); return <ModalShell title="Language" eyebrow="Speak your way" close={close}><div className="language-options"><button className={choice === 'en' ? 'selected' : ''} onClick={() => setChoice('en')}><span>English</span>{choice === 'en' && <Check size={18} />}</button><button className={choice === 'ur' ? 'selected' : ''} onClick={() => setChoice('ur')}><span>اردو</span>{choice === 'ur' && <Check size={18} />}</button></div><div className="form-actions"><button className="primary-btn full" onClick={() => { setData(prev => ({ ...prev, settings: { ...prev.settings, lang: choice } })); close() }}>Apply language</button></div></ModalShell> }

export default App

createRoot(document.getElementById('root')!).render(<App />)
